	/** A step's icon where this build reads one; nothing where it does not. */
	static final class Steps
	{
		/** A step's picture by the id the map sends, {@code itemId} or {@code spriteId}; set by name so this still runs on a step that has neither. */
		static RelayResponse.RouteStep picture(RelayResponse.RouteStep step, String field, int id)
		{
			try
			{
				Field picture = RelayResponse.RouteStep.class.getDeclaredField(field);
				picture.setAccessible(true);
				picture.set(step, id);
			}
			catch (ReflectiveOperationException absent)
			{
				/* An older step reads no picture. */
			}
			return step;
		}
	}

	/* ---- What each state does to the built panel ---- */

	static void after(String state, MapCompanionPanel panel) throws Exception
	{
		if (state.equals("route"))
		{
			/* Each other way opens with its teleport's picture. */
			expand(panel, "1 other way");
		}
		if (state.equals("slayer-open") || state.equals("slayer-expanded"))
		{
			expand(panel, "All 3 places & options");
			expand(panel, "1 kind counts");
		}
		if (state.equals("farm-bring"))
		{
			expand(panel, "Before you leave");
		}
		if (state.equals("connect"))
		{
			Pairing pairing = (Pairing) get(panel, "pairing");
			try
			{
				/* Before the pass, a Connect also said it was waiting under the field; after it, only the card does. */
				set(panel, "pendingConnectionMessage", true);
				Method say = MapCompanionPanel.class.getDeclaredMethod("say", String.class);
				say.setAccessible(true);
				say.invoke(panel, "Connecting to " + pairing.serverLabel() + "… Waiting for the map.");
				set(panel, "pendingConnectionMessage", true);
			}
			catch (NoSuchFieldException after)
			{
				/* The panel says nothing under the field after a Connect. */
			}
			((RecommendedSharing) get(panel, "recommendedSharing")).offer(pairing.serverLabel());
		}
		if (state.equals("group") || state.equals("meetup"))
		{
			press(panel, "companionView.group");
		}
		if (state.equals("meetup"))
		{
			GroupPanel group = (GroupPanel) get(panel, "groupPanel");
			group.openForm(true);
			group.title().setText("Barrows run");
		}
		if (state.startsWith("settings"))
		{
			if (!press(panel, "companion.settings"))
			{
				press(panel, "companionView.sharing");
			}
			if (state.equals("settings"))
			{
				expand(panel, "Advanced");
			}
		}
		if (state.startsWith("stars"))
		{
			StarsPanel stars = (StarsPanel) get(panel, "starsPanel");
			StarsClient client = (StarsClient) get(stars, "service");
			String feed = new String(Files.readAllBytes(Paths.get("src/test/resources/companion-stars.sample.json")), StandardCharsets.UTF_8);
			client.model.accept(new Gson().fromJson(feed, StarsModel.Feed.class));
			client.message = null;
			client.model.miningLevel = 72;
			client.model.skillTotal = 1620;
			press(panel, "companionView.stars");
			stars.refresh();
			for (StarsModel.Site site : client.model.sites())
			{
				if (site.name.equals("Rimmington mine"))
				{
					press(panel, "stars.expand." + site.key);
					press(panel, "stars.world." + site.worlds.get(0).id);
				}
			}
			if (state.equals("stars-filters"))
			{
				press(panel, "stars.filters");
			}
			if (state.equals("stars-route"))
			{
				starRouted(panel, client);
				refresh(panel);
				stars.refresh();
			}
		}
		if (state.startsWith("search"))
		{
			search(panel, state.equals("search") ? "bank" : "whip");
		}
		refresh(panel);
	}

	/**
	 * The picked star's Route, answered, by RoutePress's own steps for an answer: the star pinned as this
	 * client's destination with its way, followed from the press, as a pressed Route always is.
	 */
	static void starRouted(MapCompanionPanel panel, StarsClient client) throws Exception
	{
		StarsModel.Star star = client.model.find(client.model.selected);
		RelayResponse.Destination answer = RoutePress.destination(RoutePress.Target.tile(StarsPanel.SOURCE,
			new WorldPoint(star.x, star.y, star.plane), star.name, star.world, null), null, starRoute());
		((DestinationState) get(panel, "destinationState")).selectLocal(answer);
		((DestinationRoute) get(get(panel, "nowCards"), "destinationRoute")).adoptPressed(answer);
	}

	static void search(MapCompanionPanel panel, String query) throws Exception
	{
		SearchPanel search = (SearchPanel) get(panel, "searchPanel");
		SearchClient client = (SearchClient) get(search, "search");
		String answer = query.equals("bank")
			? "{\"rows\":["
			+ row("bank:lumbridge", "bank", "Lumbridge Castle bank", "Bank · Lumbridge Castle · 2nd floor", 3208, 3220, 2, 40, "Places") + ","
			+ row("bank:draynor", "bank", "Draynor Village bank", "Bank · Draynor Village", 3092, 3243, 0, 95, "Places") + ","
			+ row("bank:al-kharid", "bank", "Al Kharid bank", "Bank · Al Kharid", 3269, 3167, 0, 108, "Places") + ","
			+ row("npc:banker", "npc", "Banker", "Character · nearest of 112 places", 3208, 3221, 2, 40, "Places") + ","
			+ row("shop:bobs-axes", "poi", "Bob's Brilliant Axes", "Shop · Lumbridge", 3230, 3203, 0, 22, "Sold at")
			+ "],\"items\":[{\"id\":\"item:Bank filler\",\"itemId\":20594,\"name\":\"Bank filler\",\"droppedBy\":0,\"soldAt\":1}]}"
			: "{\"rows\":["
			+ row("monster:Abyssal demon", "monster", "Abyssal demon", "Slayer Tower · nearest of 6", 3417, 3566, 2, 210, "Dropped by") + ","
			+ row("monster:Abyssal Sire", "monster", "Abyssal Sire", "Abyssal Nexus", 2969, 4772, 0, 380, "Dropped by")
			+ "],\"items\":[{\"id\":\"item:Abyssal whip\",\"name\":\"Abyssal whip\",\"droppedBy\":3,\"soldAt\":0}]}";
		SearchClient.Answer parsed = new Gson().fromJson(answer, SearchClient.Answer.class);
		List<SearchClient.Hit> hits = SearchClient.normalize(parsed);
		Component box = (Component) get(search, "box");
		if (box instanceof JTextField)
		{
			((JTextField) box).setText(query);
		}
		else
		{
			box.getClass().getMethod("setText", String.class).invoke(box, query);
		}
		Object pending = get(client, "pendingTimer");
		if (pending != null)
		{
			((Runnable) pending).run();
		}
		set(client, "pendingTimer", null);
		set(client, "result", new SearchClient.Result(query, hits, null, null, false));
		search.refresh();
	}

	static String row(String id, String kind, String name, String line, int x, int y, int plane, int tiles, String section)
	{
		return "{\"id\":\"" + id + "\",\"kind\":\"" + kind + "\",\"name\":\"" + name.replace("\"", "\\\"") + "\",\"line\":\"" + line
			+ "\",\"x\":" + x + ",\"y\":" + y + ",\"plane\":" + plane + ",\"effortTiles\":" + tiles + ",\"section\":\"" + section + "\"}";
	}

	/* ---- Painting ---- */

	static void shoot(JComponent panel, String path) throws Exception
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		holder.add(panel, BorderLayout.NORTH);
		int height = Math.max(panel.getPreferredSize().height, 60);
		holder.setSize(225, height);
		layoutTree(holder);
		BufferedImage image = new BufferedImage(450, height * 2, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = image.createGraphics();
		graphics.scale(2, 2);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		holder.paint(graphics);
		graphics.dispose();
		ImageIO.write(image, "png", new File(path));
		System.out.println(path + " 225x" + height + " preferredWidth=" + panel.getPreferredSize().width);
	}

	static void layoutTree(Container parent)
	{
		parent.doLayout();
		for (Component child : parent.getComponents())
		{
			if (child instanceof Container)
			{
				layoutTree((Container) child);
			}
		}
	}

	/** The panel's private refresh, which queues its work on this thread. */
	static void refresh(MapCompanionPanel panel) throws Exception
	{
		Method method = MapCompanionPanel.class.getDeclaredMethod("refresh");
		method.setAccessible(true);
		method.invoke(panel);
	}

	static boolean press(Container parent, String name)
	{
		AbstractButton button = named(parent, name);
		if (button == null)
		{
			return false;
		}
		button.doClick();
		return true;
	}

	static AbstractButton named(Container parent, String name)
	{
		for (Component child : parent.getComponents())
		{
			if (child instanceof AbstractButton && name.equals(child.getName()))
			{
				return (AbstractButton) child;
			}
			if (child instanceof Container)
			{
				AbstractButton result = named((Container) child, name);
				if (result != null)
				{
					return result;
				}
			}
		}
		return null;
	}

	static void expand(Container parent, String text)
	{
		for (Component child : parent.getComponents())
		{
			if (child instanceof JButton && ("▸ " + text).equals(((JButton) child).getText()))
			{
				((JButton) child).doClick();
			}
			else if (child instanceof Container)
			{
				expand((Container) child, text);
			}
		}
	}

	/* ---- Reflection, for the harness's fakes ---- */

	static Object allocate(Class<?> type) throws Exception
	{
		Field f = Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe");
		f.setAccessible(true);
		Object unsafe = f.get(null);
		return unsafe.getClass().getMethod("allocateInstance", Class.class).invoke(unsafe, type);
	}

	static void set(Object target, String field, Object value) throws Exception
	{
		for (Class<?> c = target.getClass(); c != null; c = c.getSuperclass())
		{
			try
			{
				Field f = c.getDeclaredField(field);
				f.setAccessible(true);
				f.set(target, value);
				return;
			}
			catch (NoSuchFieldException e)
			{
				/* Try the superclass. */
			}
		}
		throw new NoSuchFieldException(field);
	}

	static Object get(Object target, String field) throws Exception
	{
		for (Class<?> c = target.getClass(); c != null; c = c.getSuperclass())
		{
			try
			{
				Field f = c.getDeclaredField(field);
				f.setAccessible(true);
				return f.get(target);
			}
			catch (NoSuchFieldException e)
			{
				/* Try the superclass. */
			}
		}
		throw new NoSuchFieldException(field);
	}
}

package com.pbolduc.mapcompanion;

import com.google.inject.Binder;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.JLabel;

/**
 * The renderer's stand-in for the client's sprite cache, which needs a running game.
 *
 * <p>The panel asks {@link GameSprites} for an item by id or name and an interface sprite by id;
 * this answers from the website's copies of the same files when {@code OSRS_MAP_PUBLIC} names the
 * map's {@code public} folder — {@code osrs-icons/cache/<sprite id>.png}, and the item sprites by
 * name, for the handful of ids the scenes use. Without it every picture is left empty.
 */
final class Sprites
{
	private Sprites()
	{
	}

	/** The item ids the scenes use, by the website's file for them. */
	static final Map<Integer, String> ITEMS = new HashMap<>();
	/**
	 * The spell icons the scenes use, by the website's copy of the same picture: the client's sprite
	 * cache holds the spellbook's icons, which a renderer without a running game cannot open.
	 */
	static final Map<Integer, String> SPELLS = new HashMap<>();
	/** Items the website keeps only as a travel chip, the same wiki sprite already cut to a step's 16px. */
	static final Map<Integer, String> CHIPS = new HashMap<>();

	static
	{
		ITEMS.put(314, "feather");
		ITEMS.put(2552, "ring-of-dueling-8");
		ITEMS.put(3853, "games-necklace-8");
		ITEMS.put(2722, "clue-scroll-hard");
		ITEMS.put(4151, "abyssal-whip");
		ITEMS.put(net.runelite.api.gameval.ItemID.LUNAR_TABLET_CATHERBY_TELEPORT, "catherby-teleport-tablet");
		ITEMS.put(net.runelite.api.gameval.ItemID.MYSTIC_ROBE_BOTTOM_DARK, "mystic-robe-bottom-dark");
		SPELLS.put(net.runelite.api.gameval.SpriteID.Magicon2.LUMBRIDGE_HOME_TELEPORT, "home-teleport");
		SPELLS.put(net.runelite.api.gameval.SpriteID.MagicNecroOn.DRAYNOR_MANOR_TELEPORT, "draynor-manor-teleport");
		CHIPS.put(net.runelite.api.gameval.ItemID.NZONE_TELETAB_RIMMINGTON, "teleport-tab-rimmington");
	}

	/** The same item sprite that the live client's ItemManager supplies to Drop luck. */
	static BufferedImage itemImage(int itemId)
	{
		String name = ITEMS.get(itemId);
		return name == null ? null : read(System.getenv("OSRS_MAP_PUBLIC"), "osrs-items/1x/" + name + ".png");
	}

	static void bind(Binder binder)
	{
		String root = System.getenv("OSRS_MAP_PUBLIC");
		binder.bind(GameSprites.class).toInstance(new GameSprites(null, null, null)
		{
			@Override
			void item(JLabel label, int itemId, int box)
			{
				String name = ITEMS.get(itemId);
				if (name != null)
				{
					show(label, read(root, "osrs-items/1x/" + name + ".png"), box);
				}
				else if (CHIPS.containsKey(itemId))
				{
					show(label, read(root, "osrs-icons/1x/" + CHIPS.get(itemId) + ".png"), box);
				}
			}

			@Override
			void itemNamed(JLabel label, String name, int box)
			{
				show(label, read(root, "osrs-items/1x/" + name.toLowerCase().replace("'", "").replace(' ', '-') + ".png"), box);
			}

			@Override
			void sprite(JLabel label, int spriteId, int box)
			{
				/* The combat tab's crossed swords is the one sprite the website keeps under a name of its own. */
				show(label, read(root, spriteId == net.runelite.api.gameval.SpriteID.SideIcons.COMBAT
					? "osrs-icons/1x/skill-combat.png" : SPELLS.containsKey(spriteId)
					? "osrs-icons/1x/" + SPELLS.get(spriteId) + ".png" : "osrs-icons/cache/" + spriteId + ".png"), box);
			}

			/**
			 * The world switcher's two stars are not among the website's files, so the renderer paints
			 * a stand-in of their colour and size. The client draws the game's own sprite.
			 */
			@Override
			void sprite(javax.swing.AbstractButton button, int spriteId, int box)
			{
				boolean members = spriteId == net.runelite.api.gameval.SpriteID.WorldswitcherStars.MEMBERS;
				boolean free = spriteId == net.runelite.api.gameval.SpriteID.WorldswitcherStars.FREE;
				if (!members && !free)
				{
					return;
				}
				BufferedImage star = new BufferedImage(13, 13, BufferedImage.TYPE_INT_ARGB);
				java.awt.Graphics2D g = star.createGraphics();
				g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
				java.awt.Polygon shape = new java.awt.Polygon();
				for (int i = 0; i < 10; i++)
				{
					double r = i % 2 == 0 ? 6.4 : 2.7;
					double a = Math.PI / 2 + i * Math.PI / 5;
					shape.addPoint((int) Math.round(6.5 + r * Math.cos(a)), (int) Math.round(6.5 - r * Math.sin(a)));
				}
				g.setColor(members ? new java.awt.Color(0xF5C542) : new java.awt.Color(0xC9CDD3));
				g.fillPolygon(shape);
				g.dispose();
				show(button, star, box);
			}

			@Override
			void skill(JLabel label, String name, int box)
			{
				show(label, read(root, "osrs-icons/1x/skill-" + name.toLowerCase() + ".png"), box);
			}
		});
	}

	static BufferedImage read(String root, String path)
	{
		if (root == null)
		{
			return null;
		}
		try
		{
			File file = new File(root, path);
			return file.isFile() ? ImageIO.read(file) : null;
		}
		catch (Exception e)
		{
			return null;
		}
	}
}

package com.pbolduc.mapcompanion;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.laf.RuneLiteLAF;

/**
 * Paints the real Stars tab at RuneLite's 225px with the website's own projection of a fixed set
 * of calls — `src/test/resources/companion-stars.sample.json`, written by the map's
 * `scripts/generate-companion-star-fixture.ts`. The feed is handed to the model directly, so no
 * request is made and no game runs; the client thread never drains, which is why the sidebar's
 * eligibility notice is absent rather than "Log in".
 *
 * Built on SidebarShot (in the sharing-sidebar evidence folder) for the panel itself; compile the
 * two together. States: the collapsed list, a site opened with a world picked, that world pinned
 * with hopping on, and the filter fold open with a favourite that has no star right now.
 */
public class StarsShot
{
	static Object field(Object target, String name) throws Exception
	{
		Field f = target.getClass().getDeclaredField(name);
		f.setAccessible(true);
		return f.get(target);
	}

	public static void main(String[] args) throws Exception
	{
		SwingUtilities.invokeAndWait(RuneLiteLAF::setup);
		String feed = new String(Files.readAllBytes(Paths.get("src/test/resources/companion-stars.sample.json")), StandardCharsets.UTF_8);
		for (String state : new String[]{"list", "expanded", "pinned", "filters"})
		{
			SwingUtilities.invokeAndWait(() -> {
				try
				{
					MapCompanionPanel panel = SidebarShot.build("overview");
					if (state.equals("pinned"))
					{
						HarnessConfig config = (HarnessConfig) field(panel, "config");
						config.set("enableWorldHop", true);
					}
					StarsPanel stars = (StarsPanel) field(panel, "starsPanel");
					StarsClient client = (StarsClient) field(stars, "service");
					client.model.accept(new Gson().fromJson(feed, StarsModel.Feed.class));
					client.message = null;
					client.model.miningLevel = 72;
					client.model.skillTotal = 1620;
					if (state.equals("filters"))
					{
						client.model.preferences.favorites.add(new StarsModel.Favorite("crafting guild", "Crafting Guild"));
						client.model.preferences.filters.showFreeToPlay = false;
					}
					SidebarShot.named(panel, "companionView.stars").doClick();
					stars.refresh();
					if (!state.equals("list"))
					{
						for (StarsModel.Site site : client.model.sites())
						{
							if (site.name.equals("Rimmington mine") && !state.equals("filters"))
							{
								SidebarShot.named(panel, "stars.expand." + site.key).doClick();
								SidebarShot.named(panel, "stars.world." + site.worlds.get(1).id).doClick();
							}
						}
					}
					if (state.equals("pinned")) SidebarShot.named(panel, "stars.pin").doClick();
					if (state.equals("filters")) SidebarShot.named(panel, "stars.filters").doClick();
					SidebarShot.shoot(panel, args[0] + "/stars-" + state + ".png");
				}
				catch (Exception e)
				{
					throw new RuntimeException(e);
				}
			});
		}
		System.exit(0);
	}
}

package com.pbolduc.mapcompanion;

import com.google.gson.Gson;
