import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import net.runelite.client.config.Notification;

/**
 * The plugin's settings, as a real object rather than as RuneLite's dynamic proxy.
 *
 * <p>Every method on {@link MapCompanionConfig} has a default, so this class is the interface's own
 * answers with three of them redirected: the pairing code and its suffix come out of
 * {@link HarnessStore}, because {@link Pairing} writes them there and the plugin reads them back
 * through the config, and the map address is whatever the harness was pointed at. A toggle the
 * story has not touched answers exactly what a fresh install answers — {@code
 * MapCompanionConfig.super} rather than a second copy of the defaults, so this cannot drift from
 * the settings panel.
 */
final class HarnessConfig implements MapCompanionConfig
{
	private final HarnessStore store;
	private final String mapUrl;
	private final Map<String, Boolean> toggles = new ConcurrentHashMap<>();
	private volatile String nickname = MapCompanionConfig.super.nickname();

	HarnessConfig(HarnessStore store, String mapUrl)
	{
		this.store = store;
		this.mapUrl = mapUrl;
	}

	/**
	 * Choose one category explicitly, the way a reader does in the settings panel. A sharing field
	 * RuneLite does not declare has no getter here: the plugin reads it from the store by key, as it
	 * reads RuneLite's settings, so it is written there, without the event a write there raises.
	 */
	void set(String key, boolean value)
	{
		toggles.put(key, value);
		if (!DECLARED.contains(key))
		{
			store.put(key, Boolean.toString(value));
		}
	}

	/** Every key {@link MapCompanionConfig} has a getter for. */
	private static final java.util.Set<String> DECLARED = new java.util.HashSet<>();

	static
	{
		for (java.lang.reflect.Method method : MapCompanionConfig.class.getDeclaredMethods())
		{
			net.runelite.client.config.ConfigItem item = method.getAnnotation(net.runelite.client.config.ConfigItem.class);
			if (item != null)
			{
				DECLARED.add(item.keyName());
			}
		}
	}

	/** The store this config's fields are read from, for a test that reads them as the plugin does. */
	HarnessStore store()
	{
		return store;
	}

	void nickname(String nickname)
	{
		this.nickname = nickname;
	}

	private boolean on(String key, boolean fallback)
	{
		Boolean set = toggles.get(key);
		return set == null ? fallback : set;
	}

	@Override
	public String slayerOrder()
	{
		String value = store.get("slayerOrder");
		return "single".equals(value) ? "single" : "best";
	}

	@Override
	public boolean slayerHideWilderness()
	{
		return on("slayerHideWilderness", MapCompanionConfig.super.slayerHideWilderness());
	}

	@Override
	public String pairingCode()
	{
		String held = store.get(MapCompanionConfig.KEY_PAIRING_CODE);
		return held == null ? "" : held;
	}

	@Override
	public String pairingSuffix()
	{
		String held = store.get(MapCompanionConfig.KEY_PAIRING_SUFFIX);
		return held == null ? "" : held;
	}

	@Override
	public String nickname()
	{
		return nickname;
	}

	@Override
	public String relayUrl()
	{
		return mapUrl;
	}

	@Override
	public boolean shareName()
	{
		return on(MapCompanionConfig.KEY_SHARE_NAME, MapCompanionConfig.super.shareName());
	}

	/* The switches RuneLite's list shows, which SharingGroups keeps in step with the fields below. */
	@Override
	public boolean shareMapPresence()
	{
		return on(MapCompanionConfig.KEY_SHARE_MAP_PRESENCE, MapCompanionConfig.super.shareMapPresence());
	}

	@Override
	public boolean shareProgressAndTravel()
	{
		return on(MapCompanionConfig.KEY_SHARE_PROGRESS, MapCompanionConfig.super.shareProgressAndTravel());
	}

	@Override
	public boolean shareTasksAndTimers()
	{
		return on(MapCompanionConfig.KEY_SHARE_TASKS, MapCompanionConfig.super.shareTasksAndTimers());
	}

	@Override
	public boolean shareLootAndMilestones()
	{
		return on(MapCompanionConfig.KEY_SHARE_LOOT_GROUP, MapCompanionConfig.super.shareLootAndMilestones());
	}

	@Override
	public boolean sharePosition()
	{
		return on("sharePosition", MapCompanionConfig.super.sharePosition());
	}























	@Override
	public boolean shareDeath()
	{
		return on("shareDeath", MapCompanionConfig.super.shareDeath());
	}

	@Override
	public boolean showDestination()
	{
		return on("showDestination", MapCompanionConfig.super.showDestination());
	}

	/** A notification setting toggled here is on or off with the rest as it ships, as a stored "true" reads. */
	@Override
	public Notification notifyMeetups()
	{
		Notification shipped = MapCompanionConfig.super.notifyMeetups();
		return shipped.withEnabled(on("notifyMeetups", shipped.isEnabled()));
	}

	@Override
	public boolean dropLuckChat()
	{
		return on("dropLuckChat", MapCompanionConfig.super.dropLuckChat());
	}

	@Override
	public boolean showGroupOnWorldMap()
	{
		return on("showGroupOnWorldMap", MapCompanionConfig.super.showGroupOnWorldMap());
	}

	@Override
	public boolean destinationHintArrow()
	{
		return on("destinationHintArrow", MapCompanionConfig.super.destinationHintArrow());
	}

	@Override
	public boolean drawWithShortestPath()
	{
		return on(MapCompanionConfig.KEY_SHORTEST_PATH, MapCompanionConfig.super.drawWithShortestPath());
	}

	@Override
	public boolean routeHereOnWorldMap()
	{
		return on("routeHereOnWorldMap", MapCompanionConfig.super.routeHereOnWorldMap());
	}

	@Override
	public boolean showStepOnScreen()
	{
		return on("showStepOnScreen", MapCompanionConfig.super.showStepOnScreen());
	}

	@Override
	public boolean markFarmRunInBank()
	{
		return on("markFarmRunInBank", MapCompanionConfig.super.markFarmRunInBank());
	}

	@Override
	public boolean outlineStepTeleport()
	{
		return on("outlineStepTeleport", MapCompanionConfig.super.outlineStepTeleport());
	}
