 */
final class AccountTypes
{
	static final int VARBIT = 1777;

	@Nullable
	static String name(int value)
	{
		switch (value)
		{
			case 0:
				return "normal";
			case 1:
				return "ironman";
			case 2:
				return "uim";
			case 3:
				return "hcim";
			case 4:
				return "gim";
			case 5:
				return "hcgim";
			case 6:
				return "ugim";
			default:
				return null;
		}
	}

	private AccountTypes()
	{
	}
}

