package com.pbolduc.mapcompanion;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.Player;

/**
 * Where you died.
 *
 * <p>The one piece of state in this plugin that is most useful <em>after</em> the thing it describes
 * has already gone wrong. You die, the screen sends you somewhere else, and the question is which
 * way is back and whether you can get there in time — a route calculation over your own unlocks,
 * done while a timer runs and with none of the composure that usually implies.
 *
 * <p>So it survives the death screen and it survives logging back in. Clearing it on logout would
 * throw the answer away at precisely the moment somebody wants it.
 *
 * <p>Nothing here acts. It records a tile; the map draws it and offers a route, and walking there
 * is the player's own business — the same line every other part of this plugin holds.
 *
 * <p><b>The gravestone's time left</b> is the game's own timer, read rather than guessed: how long a
 * stone stands varies, and a figure worked out here would be the guess the map's death card refuses
 * to print. It stays in this client; nothing about it joins the snapshot.
 */
@Slf4j
@Singleton
public class DeathWatcher
{
	/**
	 * After this long the marker stops being about a gravestone and starts being clutter.
	 *
	 * <p>An hour rather than the fifteen minutes a gravestone lasts, because the items are only half
	 * of it: a death in the middle of nowhere is also a walk you have to repeat, and knowing where
	 * it happened stays useful for longer than the stone does.
	 */
	private static final long FORGET_AFTER_MS = 60 * 60_000L;

	/**
	 * The most the timer may read and still be shown. {@code GRAVESTONE_DURATION} counts game ticks:
	 * the game's own HUD script turns it into seconds as ticks × 30 client cycles ÷ 50, which is 0.6
	 * a tick, and prints no time at all past 1,500, fifteen minutes ({@code [proc,gravestone_hud_resynch]}
	 * and {@code [proc,gravestone_hud_write]}). A reading past it is one the game itself does not put
	 * a number on, so neither does the card.
	 */
	static final int MOST_TICKS_SHOWN = 1_500;
	static final long TICK_MS = 600L;

	/** A gravestone standing, as the game last gave its timer. Never changes after it is made. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	static final class Stone
	{
		/** Game ticks left, by the game's own timer. */
		final int ticksLeft;
		/** The most this stone has read, so its bar is full at the first reading and drains. */
		final int ticksFull;
		/** When this stone was first seen standing: it is shown only under a death it can be from. */
		final long sinceMs;

		/** "8m left", rounded up as a countdown is, in the minutes the card's age is given in. */
		String left()
		{
			long seconds = (ticksLeft * TICK_MS + 999L) / 1000L;
			return ((seconds + 59L) / 60L) + "m left";
		}
	}

	private final Client client;

	/**
	 * Written on the client thread (the death event) and read on Swing's, once a second, for as
	 * long as the sidebar is open. Two threads, so the fields are volatile — the same reason
	 * {@link LootLog} locks every door. A torn read here would be a marker at the origin or a
	 * death that aged out a millisecond ago still drawing as fresh.
	 */
	private volatile WorldPoint diedAt = null;
	private volatile long diedAtMs = 0L;

	/**
	 * Fifteen seconds, as the other readers wait: right after a login or a hop every varbit reads
	 * zero, and the timer is not believed, nor shown, until the session has settled. Client thread.
	 */
	private final SessionSettle settle = new SessionSettle(15_000L);

	/** The stone as the last game tick read it; null while there is none or the reading is in doubt. */
	@Nullable
	private volatile Stone stone;

	@Inject
	private DeathWatcher(Client client)
	{
		this.client = client;
	}

	/** Called from the plugin, which owns every event subscription. See {@link LootLog#record}. */
	public void record(ActorDeath event)
	{
		/**
		 * Every actor's death arrives here, including every monster the player kills. Identity, not
		 * type, is the test: comparing against the local player object is what distinguishes your
		 * death from the thousands of others you cause.
		 */
		Player local = client.getLocalPlayer();
		if (local == null || event.getActor() != local)
		{
			return;
		}
		/**
		 * Through {@link WorldTiles}, so an instanced death records the template tile rather than the
		 * instance's own coordinates. This read the world location directly and was wrong for every
		 * death in an instance — which is very nearly every death at a boss, the one case this whole
		 * class exists for. A marker in an empty field is worse than no marker.
		 */
		WorldPoint at = WorldTiles.of(client, local);
		if (at == null)
		{
			/**
			 * Nothing worth a marker: an instance the client cannot resolve a template tile for. An
			 * older real death is better kept than replaced with a guess — the same choice the rest of
			 * this plugin makes when a reading will not resolve.
			 */
			return;
		}
		if (WorldTiles.ASSEMBLED.equals(WorldTiles.layout(client)))
		{
			/**
			 * The same choice for an instance put together from rooms. Its template tile is a room in
			 * the store every variant of it is kept in, not a place anybody can walk back to — the
			 * marker in an empty field again, one level down. The ones known are a raid, a house and
			 * the Gauntlet.
			 */
			return;
		}
		diedAt = at;
		diedAtMs = System.currentTimeMillis();
		log.debug("recorded a death");
	}

	/** The death worth showing, or null when there is none or it has aged out. */
	@Nullable
	public CompanionSnapshot.Death snapshot(long nowMs)
	{
		if (diedAt == null)
		{
			return null;
		}
		long age = nowMs - diedAtMs;
		if (age < 0 || age > FORGET_AFTER_MS)
		{
			return null;
		}
		CompanionSnapshot.Death death = new CompanionSnapshot.Death();
		death.tile = new CompanionSnapshot.Tile(diedAt.getX(), diedAt.getY(), diedAt.getPlane());
		death.msAgo = age;
		return death;
	}

	/** The client is up: starts the settling clock. Client thread; see {@link SessionSettle}. */
	public void onSessionResumed(long nowMs)
	{
		settle.resumed(nowMs);
	}

	/** Logged out or hopping: the timer is about to read zero, so nothing is shown until it settles. */
	public void onSessionEnded()
	{
		settle.ended();
		stone = null;
	}

	/**
	 * Read the gravestone's timer, on the game tick. Shown only while {@code GRAVESTONE_VISIBLE} says
	 * a stone stands and the timer reads something the game itself would print; any other reading,
	 * and every reading before the session settles, shows nothing rather than a doubtful number.
	 *
	 * <p>A timer that goes up is a stone placed or extended since, so it counts from now: that is
	 * what keeps a stone left by an earlier death off the card of a later one that left none.
	 */
	public void readGravestone(long nowMs)
	{
		if (!settle.settled(nowMs))
		{
			stone = null;
			return;
		}
		boolean standing = client.getVarbitValue(VarbitID.GRAVESTONE_VISIBLE) != 0;
		int ticks = client.getVarbitValue(VarbitID.GRAVESTONE_DURATION);
		if (!standing || ticks <= 0 || ticks > MOST_TICKS_SHOWN)
		{
			stone = null;
			return;
		}
		Stone last = stone;
		stone = last == null || ticks > last.ticksLeft
			? new Stone(ticks, ticks, nowMs)
			: new Stone(ticks, last.ticksFull, last.sinceMs);
	}

	/**
	 * The gravestone of the death being shown, or null: none stands, the reading is in doubt, or the
	 * stone was standing before that death and so is not its own. Any thread.
	 */
	@Nullable
	Stone gravestone(long nowMs)
	{
		Stone standing = stone;
		return standing != null && snapshot(nowMs) != null && standing.sinceMs >= diedAtMs ? standing : null;
	}

	public void clear()
	{
		diedAt = null;
		diedAtMs = 0L;
		stone = null;
	}
}

