	 */
	static final int[] DIARY_ARDOUGNE = {4458, 4459, 4460, 4461};
	static final int[] DIARY_DESERT = {4483, 4484, 4485, 4486};
	static final int[] DIARY_FALADOR = {4462, 4463, 4464, 4465};
