		readAgain();
		game.setQuest(Quest.DRAGON_SLAYER_I, QuestState.FINISHED);
		game.setVarbit(VarbitIds.DIARY_VARROCK[1], 1);
		readAgain();
		toggle(MapCompanionConfig.KEY_SHARE_MILESTONES, true);
