		star.y = 3240;
		star.plane = 0;
		star.name = "Rimmington mine";
		star.world = 302;
		star.note = "T7 · 16m left";
		return star;
	}

	/** The reply fixture's destination with its route, as the map sends it and the next tick takes it. */
