	public void endStopsLocallyAndNamesTheRunItMayDelete() throws Exception
	{
		connect();
		RelayResponse.FarmRun run = example();
		state.acceptFor(identity.id(), EPOCH, run, 1, System.currentTimeMillis());
		status.set(204);
