package com.pbolduc.mapcompanion;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The meetup reminder is off until asked for, and then says each meetup once, when it was asked to. */
public class MeetupReminderTest
{
	private static final long NOW = 1_800_000_000_000L;

	@Test
	public void isOffByDefault()
	{
		MapCompanionConfig defaults = new MapCompanionConfig()
		{
		};
		assertFalse("the reminder is opt-in", defaults.notifyMeetups().isEnabled());
		assertEquals(5, defaults.meetupReminderMinutes());

		MeetupReminder reminder = new MeetupReminder();
		List<MeetupReminder.Upcoming> soon = Collections.singletonList(new MeetupReminder.Upcoming("hunt", "Star hunt", NOW + 60_000L));
		assertTrue("nothing is said while it is off", reminder.due(soon, NOW, defaults.notifyMeetups().isEnabled(), 5).isEmpty());
	}

	@Test
	public void saysEachMeetupOnceAtTheChosenLead()
	{
		MeetupReminder reminder = new MeetupReminder();
		List<MeetupReminder.Upcoming> week = Arrays.asList(
			new MeetupReminder.Upcoming("hunt", "Star hunt", NOW + 20 * 60_000L),
			new MeetupReminder.Upcoming("raids", "Raids", NOW + 26 * 3_600_000L));
		assertTrue("twenty minutes out is not yet fifteen", reminder.due(week, NOW, true, 15).isEmpty());
		assertEquals(Collections.singletonList("Meetup: Star hunt starts in 15m"),
			reminder.due(week, NOW + 5 * 60_000L, true, 15));
		assertTrue("once", reminder.due(week, NOW + 10 * 60_000L, true, 15).isEmpty());

		/* Moved to another hour, it is a new time to be told about. */
		List<MeetupReminder.Upcoming> moved = Collections.singletonList(
			new MeetupReminder.Upcoming("hunt", "Star hunt", NOW + 75 * 60_000L));
		assertEquals(1, reminder.due(moved, NOW + 65 * 60_000L, true, 15).size());
	}

	/** An untitled meetup is a meetup, not "somewhere", which would read as where it is. */
	@Test
	public void anUntitledMeetupIsAMeetup()
	{
		assertEquals(Collections.singletonList("A meetup starts in 1m"), new MeetupReminder().due(
			Collections.singletonList(new MeetupReminder.Upcoming("hunt", null, NOW + 60_000L)), NOW, true, 5));
		assertEquals(Collections.singletonList("A meetup starts in 1m"), new MeetupReminder().due(
			Collections.singletonList(new MeetupReminder.Upcoming("hunt", "  ", NOW + 60_000L)), NOW, true, 5));
		assertEquals(Collections.singletonList("A meetup is starting"), new MeetupReminder().due(
			Collections.singletonList(new MeetupReminder.Upcoming("hunt", "", NOW)), NOW, true, 5));
		assertEquals("a titled one keeps its title", Collections.singletonList("Meetup: Star hunt is starting"),
			new MeetupReminder().due(Collections.singletonList(new MeetupReminder.Upcoming("hunt", "Star hunt", NOW)), NOW, true, 5));
	}

	@Test
	public void aMeetupLongStartedIsNotNews()
	{
		MeetupReminder reminder = new MeetupReminder();
		List<MeetupReminder.Upcoming> past = Collections.singletonList(new MeetupReminder.Upcoming("hunt", "Star hunt", NOW - 10 * 60_000L));
		assertTrue(reminder.due(past, NOW, true, 5).isEmpty());
	}

	/*
	 * Rewritten when the map's older single meetup stopped being read: every map this plugin talks to
	 * sends the week's meetups, so they are the only thing a reminder can come from, each under its
	 * own id, and a map that sends none reminds of nothing.
	 */
	@Test
	public void theWeeksMeetupsAreWhatIsWatched()
	{
		RelayResponse.Meetup hunt = new RelayResponse.Meetup();
		hunt.id = "hunt";
		hunt.title = "Star hunt";
		hunt.startsAtMs = NOW;
		RelayResponse.Meetup raid = new RelayResponse.Meetup();
		raid.id = "raid";
		raid.title = "Raids";
		raid.startsAtMs = NOW + 60_000L;
		List<MeetupReminder.Upcoming> watched = MeetupReminder.of(Arrays.asList(hunt, raid));
		assertEquals(2, watched.size());
		assertEquals("hunt", watched.get(0).key);
		assertEquals("raid", watched.get(1).key);
		assertTrue(MeetupReminder.of(Collections.<RelayResponse.Meetup>emptyList()).isEmpty());
		assertTrue(MeetupReminder.of(null).isEmpty());
	}
}

