		state.observePorts(Arrays.asList(empty(0), courier(1, 84, 3, 0), courier(2, 2, 0, 0), bounty(3, 466, 9), empty(4)));
		assertTrue(state.view().changed);
		assertFalse("a change ticks nothing", state.view().done.contains(1));
