			int from = text.indexOf(SharingFields.NAME.label);
			assertTrue(from >= 0 && text.contains(SharingFields.NAME.detail));
			for (SharingFields.Section section : SharingFields.GROUPS)
			{
				from = text.indexOf(section.title, from);
