/** An update is told once, to a player who used the plugin before, and never to a new one. */
public class UpdateNoticeTest
{
	@Test
	public void aPlayerWhoUsedTheLastVersionHearsTheLineOnce()
	{
		HarnessStore store = new HarnessStore();
		assertEquals(UpdateNotice.LINE, UpdateNotice.due(store, true));
		assertNull("the second login of the same version says nothing", UpdateNotice.due(store, true));
		assertEquals(CompanionVersion.VERSION, store.get(UpdateNotice.KEY_TOLD));
	}

	@Test
	public void aFreshInstallRecordsTheVersionWithoutAWord()
	{
		HarnessStore store = new HarnessStore();
		assertNull(UpdateNotice.due(store, false));
		assertEquals(CompanionVersion.VERSION, store.get(UpdateNotice.KEY_TOLD));
		assertNull("connecting later is not an update", UpdateNotice.due(store, true));
	}

	@Test
	public void theNextVersionIsToldEvenToAPlayerNotConnectedNow()
	{
		HarnessStore store = new HarnessStore();
		store.set(UpdateNotice.KEY_TOLD, "1.0.0");
		assertEquals(UpdateNotice.LINE, UpdateNotice.due(store, false));
	}

	/**
	 * The line is said under the version number as what that version changed, so a release that moves
	 * the number without writing a new line would greet every updated player with the last release's
	 * news. Write the line for the new version, then move {@link CompanionVersion#LINE_VERSION}.
	 */
	@Test
	public void theLineWasWrittenForTheVersionItIsSaidUnder()
	{
		assertEquals("CompanionVersion.VERSION moved and UpdateNotice.LINE still describes " + CompanionVersion.LINE_VERSION
			+ ": write what this version changed, then move LINE_VERSION", CompanionVersion.VERSION, CompanionVersion.LINE_VERSION);
	}
}

