	/** The instance parser, because the client's Gson (2.8.5) predates the static one. */
	@SuppressWarnings("deprecation")
	private static JsonElement parse(String json)
	{
		return new JsonParser().parse(json);
	}

	/**
	 * Every public instance field of this plugin's own classes is non-null, walking into nested
	 * objects, lists and maps. For a list of one class, a field counts as set when any element
	 * sets it — which is how the two kinds of milestone share one class — and that holds at every
	 * depth: a friend's news is a level for one friend and a drop for the next, so its skill and its
	 * item are each vouched for by whichever friend's news has one.
	 */
	private static CompanionSnapshot.PortTaskSlot portSlot(int slot, String state, Integer taskId, Integer taken,
		Integer delivered, Integer remaining)
	{
		CompanionSnapshot.PortTaskSlot w = new CompanionSnapshot.PortTaskSlot();
		w.slot = slot;
		w.state = state;
		w.taskId = taskId;
		w.taken = taken;
		w.delivered = delivered;
		w.remaining = remaining;
		return w;
	}

	/**
	 * The reply's run with the port-task fixture's stops beside its own, so a stop's fields are set
	 * when either kind of run sets them. Every other field of a run is still the reply's own to fill:
	 * the port-task fixture brings nothing to bring, no patch and no item.
	 */
	private static void withPortTaskStops(RelayResponse.FarmRun run) throws IOException
	{
		String json = new String(Files.readAllBytes(PORT_TASK_RUN), StandardCharsets.UTF_8);
		RelayResponse.FarmRun ports = new Gson().fromJson(json, RelayResponse.FarmRun.class);
		assertEquals(FarmRunWire.PORT_TASKS, ports.kind);
		List<RelayResponse.FarmStop> stops = new ArrayList<>(run.stops);
		stops.addAll(ports.stops);
		run.stops = stops;
	}

	private static void assertEveryFieldSet(String path, Object value)
	{
		List<String> missing = new ArrayList<>();
		collectUnset(path, value, missing);
		if (!missing.isEmpty())
		{
			fail("fields the fixture leaves unset, so the contract cannot vouch for them: " + missing);
		}
	}

	private static void collectUnset(String path, Object value, List<String> missing)
	{
		if (value == null)
		{
			missing.add(path);
			return;
		}
		if (value instanceof Map)
		{
			if (((Map<?, ?>) value).isEmpty())
			{
				missing.add(path + " (empty)");
			}
			return;
		}
		if (value instanceof Collection)
		{
			Collection<?> items = (Collection<?>) value;
			if (items.isEmpty())
			{
				missing.add(path + " (empty)");
				return;
			}
			Object first = items.iterator().next();
			if (!ours(first.getClass()))
			{
				return;
			}
			for (Field field : publicFields(first.getClass()))
			{
				List<String> unsetInEvery = null;
				for (Object item : items)
				{
					if (read(field, item) != null)
					{
						List<String> nested = new ArrayList<>();
						collectUnset(path + "[]." + field.getName(), read(field, item), nested);
						if (unsetInEvery == null)
						{
							unsetInEvery = nested;
						}
						else
						{
							unsetInEvery.retainAll(nested);
						}
					}
				}
				if (unsetInEvery == null)
				{
					missing.add(path + "[]." + field.getName());
				}
				else
				{
					missing.addAll(unsetInEvery);
				}
			}
			return;
		}
		if (!ours(value.getClass()))
		{
			return;
		}
		for (Field field : publicFields(value.getClass()))
		{
			collectUnset(path + "." + field.getName(), read(field, value), missing);
		}
	}

	private static boolean ours(Class<?> type)
	{
		return type.getName().startsWith("com.pbolduc.mapcompanion.");
	}

	private static List<Field> publicFields(Class<?> type)
	{
		List<Field> out = new ArrayList<>();
		for (Field field : type.getFields())
		{
			if (!Modifier.isStatic(field.getModifiers()))
			{
				out.add(field);
			}
		}
		return out;
	}

	private static Object read(Field field, Object owner)
	{
		try
		{
			return field.get(owner);
		}
		catch (IllegalAccessException e)
		{
			throw new AssertionError(e);
		}
	}
}

